import{_ as s,o as i,c as o,ae as t}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"CVP Evidence Gate (Slice 4 of 5)","description":"","frontmatter":{},"headers":[],"relativePath":"plans/tasks/cvp-evidence.md","filePath":"plans/tasks/cvp-evidence.md"}'),a={name:"plans/tasks/cvp-evidence.md"};function c(n,e,d,l,r,h){return i(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="cvp-evidence-gate-slice-4-of-5" tabindex="-1">CVP Evidence Gate (Slice 4 of 5) <a class="header-anchor" href="#cvp-evidence-gate-slice-4-of-5" aria-label="Permalink to &quot;CVP Evidence Gate (Slice 4 of 5)&quot;">​</a></h1><p><strong>Status:</strong> Merged to <code>main</code> as commit <code>b66707a4</code> (PR <a href="https://github.com/KooshaPari/HeliosLab/pull/203" target="_blank" rel="noreferrer">#203</a>) — Slice 4 of 5. <strong>Slice 6 progress:</strong> F3 freshness gate landed on <code>wbs/cvp-freshness</code> and shipped as PR <a href="https://github.com/KooshaPari/HeliosLab/pull/205" target="_blank" rel="noreferrer">#205</a>. Remaining follow-ups F1, F2, F4 tracked in <a href="./../WBS.html"><code>docs/plans/WBS.md</code></a>. <strong>See also:</strong> <a href="./../WBS.html"><code>docs/plans/WBS.md</code></a>. <strong>Branch:</strong> <code>wbs/cvp</code> (deleted post-merge). <strong>Scope:</strong> Land CVP evidence on main + add a CI gate that validates the committed JSON.</p><hr><h2 id="what-this-slice-delivers" tabindex="-1">What this slice delivers <a class="header-anchor" href="#what-this-slice-delivers" aria-label="Permalink to &quot;What this slice delivers&quot;">​</a></h2><p>Slice 4 puts the Customer Validation Pack (CVP) onto <code>main</code> and adds a CI gate that prevents regressions in the documented 1000-concurrent- session claim.</p><p>Two pieces:</p><ol><li><p><strong>CVP evidence</strong> (one file cherry-picked from <code>origin/wbs/terminal-slice</code>):</p><ul><li><code>docs/cvp/cvp-1000.json</code> — the committed 1000-lane evidence.</li></ul><p>The CVP harness (<code>apps/runtime/tests/cvp/cvp-harness.ts</code>) and its regression suite were considered for cherry-pick too, but both depend on terminal-first work (<code>VerticalSliceDriver</code>, <code>RecordingRendererAdapter</code>) that hasn&#39;t landed on <code>main</code> yet. The harness stays opt-in (<code>CVP_SCALING=1 CVP_TARGET=1000</code>) on the terminal-slice branch and will be cherry-picked alongside its dependencies in a follow-up. The 1000-lane JSON is evidence only; it doesn&#39;t import anything.</p></li><li><p><strong>CI gate</strong> (new files):</p><ul><li><code>scripts/cvp-evidence-validate.ts</code> (~430 lines) — five checks against the committed JSON.</li><li><code>scripts/tests/cvp-evidence-validate.test.ts</code> (~350 lines, 27 tests) — every check covered.</li><li><code>.github/workflows/cvp-evidence.yml</code> (~85 lines) — runs on every pull request targeting <code>main</code> and on <code>workflow_dispatch</code>.</li><li><code>.github/required-checks.txt</code> — adds <code>cvp-evidence.yml|CVP Evidence</code>.</li></ul></li></ol><h2 id="validator-script-and-tests" tabindex="-1">Validator script and tests <a class="header-anchor" href="#validator-script-and-tests" aria-label="Permalink to &quot;Validator script and tests&quot;">​</a></h2><p><code>scripts/cvp-evidence-validate.ts</code> exports:</p><ul><li><code>readCvpReport(path)</code> — parses the JSON; returns <code>null</code> on missing / invalid input.</li><li><code>checkSchema(report)</code> — <code>schema === &quot;helios.cvp.v1&quot;</code> (skip when no evidence is committed yet).</li><li><code>checkOverallPass(report)</code> — <code>overallPass === true</code>.</li><li><code>checkPerCheckFlags(report)</code> — every entry in <code>pass.*</code> is true.</li><li><code>checkThresholdBounds(report)</code> — every measurement is within the thresholds the harness itself computed (<code>thresholds.*</code>).</li><li><code>checkFreshness(report, opts)</code> — <code>generatedAt</code> is within <code>maxAgeDays</code> of <code>now</code>; <code>maxAgeDays === 0</code> disables (returns <code>skip</code>).</li><li><code>evaluateCvpReport(report, opts)</code> — runs all five checks; returns findings.</li><li>Constants: <code>EXPECTED_SCHEMA</code>, <code>EXPECTED_COUNT</code>, <code>PASS_KEYS</code>, <code>DEFAULT_EVIDENCE_PATH</code>, <code>REPORT_PATH</code>, <code>DEFAULT_MAX_AGE_DAYS = 90</code>, <code>MS_PER_DAY</code>.</li><li>CLI: <code>--file PATH</code>, <code>--commit SHA</code>, <code>--max-age-days N</code>, <code>--now ISO</code>.</li></ul><p>The CLI writes <code>.gate-reports/cvp-evidence.json</code> (machine-readable) and a human summary on stdout. Exits 0 iff every check is <code>pass</code> or <code>skip</code>.</p><p><code>scripts/tests/cvp-evidence-validate.test.ts</code> covers:</p><ul><li><code>readCvpReport</code> (3 tests): valid, missing, invalid-JSON.</li><li><code>checkSchema</code> (3 tests): pass, wrong schema, null.</li><li><code>checkOverallPass</code> (2 tests): pass, fail.</li><li><code>checkPerCheckFlags</code> (3 tests): pass, single-flag fail, all-flags fail.</li><li><code>checkThresholdBounds</code> (6 tests): pass; per-check fails for lanesBound / spawn p99 / cleanup / memory / total.</li><li><code>checkFreshness</code> (6 tests): well-within, exact-boundary pass, just-past-boundary fail, <code>maxAgeDays=0</code> skip, null-report skip, bad-<code>generatedAt</code> fail.</li><li><code>evaluateCvpReport</code> (3 tests): all-pass (5/5), fail-finding (5 findings, ≥1 fail), all-skip on null (5/5).</li><li><code>module exports</code> (1 test): constant stability (<code>DEFAULT_MAX_AGE_DAYS === 90</code>, <code>MS_PER_DAY === 86_400_000</code>).</li></ul><h2 id="how-to-verify-locally" tabindex="-1">How to verify locally <a class="header-anchor" href="#how-to-verify-locally" aria-label="Permalink to &quot;How to verify locally&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the validator against the committed evidence</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cvp-evidence-validate.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the unit tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/cvp-evidence-validate.test.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Biome check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package=@biomejs/biome@2.5.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> biome</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cvp-evidence-validate.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/cvp-evidence-validate.test.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Static analysis gate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gate-static-analysis.ts</span></span></code></pre></div><p>All four should exit 0.</p><h2 id="workflow-design-notes" tabindex="-1">Workflow design notes <a class="header-anchor" href="#workflow-design-notes" aria-label="Permalink to &quot;Workflow design notes&quot;">​</a></h2><ul><li><strong>No <code>workflow_run</code> here.</strong> Unlike the release-evidence gate (slice 3), this one does not need to follow another workflow. The committed JSON is small enough to inspect on every PR.</li><li><strong>No harness execution in CI.</strong> Running 1000 concurrent PTYs on a GitHub-hosted runner is expensive and load-sensitive; the harness stays opt-in via <code>CVP_SCALING=1</code> for local / scheduled execution.</li><li><strong>Job status drives the check.</strong> GitHub maps <code>job.conclusion</code> to the PR&#39;s check status automatically; no <code>gh api</code> calls needed.</li><li><strong>Manual dispatch supported.</strong> Operators can re-validate any commit without opening a PR.</li><li><strong>Skip-on-missing.</strong> Until the harness lands on main, the JSON may not be present in every PR; the gate skips rather than fails when no evidence is committed yet.</li></ul><h2 id="what-is-enforced-today" tabindex="-1">What is enforced today <a class="header-anchor" href="#what-is-enforced-today" aria-label="Permalink to &quot;What is enforced today&quot;">​</a></h2><p>A <code>pull_request</code> against <code>main</code> is blocked at the branch-protection layer unless <code>cvp-evidence.yml|CVP Evidence</code> succeeds. With <code>docs/cvp/cvp-1000.json</code> committed, the gate fails if any of:</p><ul><li>The schema is not <code>helios.cvp.v1</code>.</li><li><code>overallPass</code> is <code>false</code>.</li><li>Any of <code>pass.lanesBound</code>, <code>pass.totalDuration</code>, <code>pass.spawnLatency</code>, <code>pass.cleanupLatency</code>, <code>pass.memoryStability</code> is <code>false</code>.</li><li>Any measurement exceeds its <code>thresholds.*</code> bound (defence in depth).</li><li><code>generatedAt</code> is more than 90 days old (override per-repo via the <code>CVP_MAX_AGE_DAYS</code> variable; <code>0</code> disables the freshness check).</li></ul><p>When the JSON file is missing, the gate skips all five checks and exits 0.</p><h2 id="what-is-not-yet-enforced" tabindex="-1">What is not yet enforced <a class="header-anchor" href="#what-is-not-yet-enforced" aria-label="Permalink to &quot;What is not yet enforced&quot;">​</a></h2><ul><li><strong>Per-release JSON files.</strong> Today only <code>cvp-1000.json</code> is gated. Once the harness is wired into the release pipeline, each release should publish its own <code>cvp-&lt;version&gt;.json</code> and the gate should validate the most recent one.</li><li><strong>CVP harness and regression suite.</strong> The 25/100/250-lane scaling regression suite (<code>apps/runtime/tests/cvp/cvp-scaling.test.ts</code>) and the 1000-lane harness (<code>apps/runtime/tests/cvp/cvp-harness.ts</code>) stay on <code>origin/wbs/terminal-slice</code> until terminal-first lands on main. Both import <code>VerticalSliceDriver</code> and <code>RecordingRendererAdapter</code>, which are terminal-first deliverables.</li></ul><h2 id="follow-ups-not-in-this-slice" tabindex="-1">Follow-ups (not in this slice) <a class="header-anchor" href="#follow-ups-not-in-this-slice" aria-label="Permalink to &quot;Follow-ups (not in this slice)&quot;">​</a></h2><ul><li>Refresh <code>docs/cvp/cvp-1000.json</code> on every release commit, scoped to the same SHA via a <code>workflow_run</code> follower pattern.</li><li>Land <code>VerticalSliceDriver</code> + <code>RecordingRendererAdapter</code> (slice 1 / slice 2 follow-ups) so the harness and scaling regression suite can come over too.</li><li>Wire <code>bun run cvp:scaling</code> into a weekly scheduled job so the regression suite catches drift before it affects the 1000-lane claim.</li></ul>`,26)])])}const v=s(a,[["render",c]]);export{u as __pageData,v as default};
